//! How each platform answers Kotlin's character questions, generated by running
//! `tools/JavaChars.java` there (`tools/generate-char-tables.sh`).
//!
//! Kotlin asks `java.lang.Character`, which on Android is ICU and differs from a computer's JVM for
//! some characters: Android's `isLowerCase` and `isUpperCase` are only the categories Ll and Lu
//! (not ª or Ⅻ), its regex `\s` is all of Unicode's White_Space rather than ASCII's, and it counts
//! U+180E as whitespace. So the library built for Android answers as Android does, and the one
//! built for a computer, which the JVM tests load, as the JVM does.

#[cfg(any(test, target_os = "android"))]
pub(crate) mod android;
#[cfg(any(test, not(target_os = "android")))]
pub(crate) mod jvm;

#[cfg(target_os = "android")]
pub(crate) use android::TABLES;
#[cfg(not(target_os = "android"))]
pub(crate) use jvm::TABLES;

/// One platform's answers for every UTF-16 unit.
#[derive(Debug)]
pub(crate) struct Tables {
    /// Where each run of units with the same flags starts, ascending from 0.
    pub flag_starts: &'static [u16],
    /// Each run's flags: `LETTER`, `DIGIT` and so on in lib.rs.
    pub flags: &'static [u8],
    /// The units whose `Character.toUpperCase` differs from themselves, ascending.
    pub upper_from: &'static [u16],
    /// Their upper case, in the same order.
    pub upper_to: &'static [u16],
    /// The units whose `Character.toLowerCase` differs from themselves, ascending.
    pub lower_from: &'static [u16],
    /// Their lower case, in the same order.
    pub lower_to: &'static [u16],
}

impl Tables {
    pub fn flags(&self, unit: u16) -> u8 {
        // The first run starts at 0, so every unit is in one.
        let run = self.flag_starts.partition_point(|&start| start <= unit) - 1;
        self.flags[run]
    }

    pub fn upper(&self, unit: u16) -> u16 {
        map(unit, self.upper_from, self.upper_to)
    }

    pub fn lower(&self, unit: u16) -> u16 {
        map(unit, self.lower_from, self.lower_to)
    }
}

fn map(unit: u16, from: &[u16], to: &[u16]) -> u16 {
    from.binary_search(&unit).map_or(unit, |i| to[i])
}
